def get_user_answer(question):
    """Get user input for a trivia question."""
    while True:
        user_answer = input(f"Question: {question}.\nYour answer: ").strip().lower()
        if user_answer in ["a", "b", "c", "d"]:
            return user_answer
        else:
            print("Please enter 'a', 'b', 'c', or 'd'.")

def check_answer(question, correct_answer):
    """Check user answer and display result."""
    user_answer = get_user_answer(question)
    if user_answer == correct_answer:
        print(f"Correct! You now have {question + 1} point.")
    else:
        print(f"Incorrect. The correct answer is {correct_answer}. You now have {question} point.")

def play_trivia():
    """Play the trivia game."""
    questions = [
        "Who is the capital of France?", "What is the name of the main character in 'To Kill a Mockingbird'?",
        "Which country has the most UNESCO World Heritage Sites?", "What is the name of the first book in the Harry Potter series?",
        "What is the name of the currency used in Japan?",
    ]

    score = 0
    for question in questions:
        correct_answer = questions[questions.index(question) + 1]
        check_answer(question, correct_answer)
        score += 1

    print(f"\nYour final score is {score} points.")

if __name__ == "__main__":
    play_trivia()
```

This program will ask the user a series of trivia questions, taking their answers as input and keeping track of the score. The user will be prompted to enter 'a', 'b', 'c', or 'd' for each question. The program will display the correct answer and the user's score for each question.
